-- @@ documents 0005_alter_document_checksum_unique
-- AlterField unique=True → False: Django looks up the unique constraints of the column by introspection
-- (the name depends on the age of the installation) – here likewise via the catalog instead of a fixed name.
DO $$ DECLARE r record; BEGIN FOR r IN SELECT con.conname FROM pg_constraint con JOIN pg_class c ON c.oid = con.conrelid JOIN pg_namespace ns ON ns.oid = c.relnamespace AND ns.nspname = current_schema() WHERE c.relname = 'documents_document' AND con.contype = 'u' AND con.conkey = ARRAY[(SELECT attnum FROM pg_attribute WHERE attrelid = c.oid AND attname = 'checksum')]::int2[] LOOP EXECUTE format('ALTER TABLE "documents_document" DROP CONSTRAINT %I', r.conname); END LOOP; END $$;
DROP INDEX IF EXISTS "documents_document_checksum_75209391_like";

