-- @@ documents 0007_sharelinkbundle
CREATE TABLE "documents_sharelinkbundle" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "created" timestamp with time zone NOT NULL, "expiration" timestamp with time zone NULL, "slug" varchar(50) NOT NULL UNIQUE, "file_version" varchar(50) NOT NULL, "status" varchar(50) NOT NULL, "size_bytes" integer NULL CHECK ("size_bytes" >= 0), "last_error" jsonb NULL, "file_path" varchar(512) NOT NULL, "built_at" timestamp with time zone NULL, "owner_id" integer NULL);
CREATE TABLE "documents_sharelinkbundle_documents" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "sharelinkbundle_id" integer NOT NULL, "document_id" integer NOT NULL);
-- RunPython grant_share_link_bundle_permissions (translated by hand): create_permissions creates
-- the ContentType and the four default permissions of the new model (order add/change/delete/view
-- like Django), then all users and groups with the permission `add_document` (directly
-- assigned, like upstream) get the four permissions added; existing assignments remain.
INSERT INTO "django_content_type" ("app_label", "model") SELECT 'documents', 'sharelinkbundle' WHERE NOT EXISTS (SELECT 1 FROM "django_content_type" WHERE "app_label" = 'documents' AND "model" = 'sharelinkbundle');
INSERT INTO "auth_permission" ("name", "content_type_id", "codename") SELECT v.name, ct.id, v.codename FROM "django_content_type" ct CROSS JOIN (VALUES (1, 'Can add share link bundle', 'add_sharelinkbundle'), (2, 'Can change share link bundle', 'change_sharelinkbundle'), (3, 'Can delete share link bundle', 'delete_sharelinkbundle'), (4, 'Can view share link bundle', 'view_sharelinkbundle')) AS v(o, name, codename) WHERE ct.app_label = 'documents' AND ct.model = 'sharelinkbundle' AND NOT EXISTS (SELECT 1 FROM "auth_permission" p WHERE p.content_type_id = ct.id AND p.codename = v.codename) ORDER BY v.o;
INSERT INTO "auth_user_user_permissions" ("user_id", "permission_id") SELECT u.user_id, sp.id FROM (SELECT DISTINCT up.user_id FROM "auth_user_user_permissions" up WHERE up.permission_id = (SELECT p.id FROM "auth_permission" p JOIN "django_content_type" c ON c.id = p.content_type_id WHERE p.codename = 'add_document' ORDER BY c.app_label, c.model, p.codename LIMIT 1)) u CROSS JOIN (SELECT id FROM "auth_permission" WHERE codename LIKE '%sharelinkbundle%') sp WHERE NOT EXISTS (SELECT 1 FROM "auth_user_user_permissions" x WHERE x.user_id = u.user_id AND x.permission_id = sp.id) ORDER BY u.user_id, sp.id;
INSERT INTO "auth_group_permissions" ("group_id", "permission_id") SELECT g.group_id, sp.id FROM (SELECT DISTINCT gp.group_id FROM "auth_group_permissions" gp WHERE gp.permission_id = (SELECT p.id FROM "auth_permission" p JOIN "django_content_type" c ON c.id = p.content_type_id WHERE p.codename = 'add_document' ORDER BY c.app_label, c.model, p.codename LIMIT 1)) g CROSS JOIN (SELECT id FROM "auth_permission" WHERE codename LIKE '%sharelinkbundle%') sp WHERE NOT EXISTS (SELECT 1 FROM "auth_group_permissions" x WHERE x.group_id = g.group_id AND x.permission_id = sp.id) ORDER BY g.group_id, sp.id;
ALTER TABLE "documents_sharelinkbundle" ADD CONSTRAINT "documents_sharelinkbundle_owner_id_9138d0af_fk_auth_user_id" FOREIGN KEY ("owner_id") REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED;
