-- @@ documents 0014_savedview_visibility_to_ui_settings
-- RunPython _set_default_visibility_ids (translated by hand): every user gets a
-- UiSettings row (get_or_create, settings = {}); in settings.saved_views
-- dashboard_views_visible_ids / sidebar_views_visible_ids are set if they are missing or null:
-- IDs of the user's own views with show_on_dashboard or show_in_sidebar, sorted like
-- SavedView.Meta.ordering ("name"). No object as settings/saved_views → {} (like upstream).
INSERT INTO "documents_uisettings" ("user_id", "settings") SELECT u.id, '{}'::jsonb FROM "auth_user" u WHERE NOT EXISTS (SELECT 1 FROM "documents_uisettings" s WHERE s.user_id = u.id) ORDER BY u.id;
UPDATE "documents_uisettings" s SET "settings" = n.new FROM (SELECT x.id, x.cur || jsonb_build_object('saved_views', x.sv || CASE WHEN x.sv->'dashboard_views_visible_ids' IS NULL OR x.sv->'dashboard_views_visible_ids' = 'null'::jsonb THEN jsonb_build_object('dashboard_views_visible_ids', COALESCE((SELECT jsonb_agg(v.id ORDER BY v.name, v.id) FROM "documents_savedview" v WHERE v.owner_id = x.user_id AND v.show_on_dashboard), '[]'::jsonb)) ELSE '{}'::jsonb END || CASE WHEN x.sv->'sidebar_views_visible_ids' IS NULL OR x.sv->'sidebar_views_visible_ids' = 'null'::jsonb THEN jsonb_build_object('sidebar_views_visible_ids', COALESCE((SELECT jsonb_agg(v.id ORDER BY v.name, v.id) FROM "documents_savedview" v WHERE v.owner_id = x.user_id AND v.show_in_sidebar), '[]'::jsonb)) ELSE '{}'::jsonb END) AS new FROM (SELECT c.id, c.user_id, c.cur, CASE WHEN jsonb_typeof(c.cur->'saved_views') = 'object' THEN c.cur->'saved_views' ELSE '{}'::jsonb END AS sv FROM (SELECT id, user_id, CASE WHEN jsonb_typeof("settings") = 'object' THEN "settings" ELSE '{}'::jsonb END AS cur FROM "documents_uisettings" WHERE user_id IN (SELECT id FROM "auth_user")) c) x) n WHERE s.id = n.id AND s."settings" IS DISTINCT FROM n.new;
ALTER TABLE "documents_savedview" DROP COLUMN "show_on_dashboard" CASCADE;
ALTER TABLE "documents_savedview" DROP COLUMN "show_in_sidebar" CASCADE;

