-- @@ paperless 0008_replace_skip_archive_file
ALTER TABLE "paperless_applicationconfiguration" ADD COLUMN "archive_file_generation" varchar(8) NULL;
-- RunPython migrate_old_values (translated by hand): mode skip/skip_noarchive → auto;
-- skip_archive_file never → always, with_text → auto, always → never; skip_noarchive without
-- skip_archive_file → never.
UPDATE "paperless_applicationconfiguration" SET "mode" = CASE WHEN "mode" IN ('skip', 'skip_noarchive') THEN 'auto' ELSE "mode" END, "archive_file_generation" = CASE "skip_archive_file" WHEN 'never' THEN 'always' WHEN 'with_text' THEN 'auto' WHEN 'always' THEN 'never' ELSE CASE WHEN "mode" = 'skip_noarchive' AND "skip_archive_file" IS NULL THEN 'never' ELSE "archive_file_generation" END END;
ALTER TABLE "paperless_applicationconfiguration" DROP COLUMN "skip_archive_file" CASCADE;

