-- RunPython clamp_mailrule_order (translated by hand): only if a value lies outside smallint,
-- renumber all rules by (order, id) (0, 1, 2, …).
UPDATE "paperless_mail_mailrule" r SET "order" = n.rn - 1 FROM (SELECT id, row_number() OVER (ORDER BY "order", id) AS rn FROM "paperless_mail_mailrule") n WHERE r.id = n.id AND EXISTS (SELECT 1 FROM "paperless_mail_mailrule" WHERE "order" > 32767 OR "order" < -32768);
ALTER TABLE "paperless_mail_mailrule" ALTER COLUMN "order" TYPE smallint USING "order"::smallint;
ALTER TABLE "paperless_mail_mailrule" ALTER COLUMN "pdf_layout" TYPE smallint USING "pdf_layout"::smallint;

