ALTER TABLE "paperless_mail_mailrule" ADD COLUMN "stop_processing" boolean DEFAULT false NOT NULL;
ALTER TABLE "paperless_mail_mailrule" ALTER COLUMN "stop_processing" DROP DEFAULT;

